cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);

// Basic stats
const totalOrders = data.length;
const confirmed = data.filter(r => r.Status === 'confirmed');
const cancelled = data.filter(r => r.Status === 'cancelled');
const totalRevenue = confirmed.reduce((s, r) => s + r['Total Paid'], 0);
const cancelledValue = cancelled.reduce((s, r) => s + r['Total Paid'], 0);

console.log('=== OVERVIEW ===');
console.log('Total orders:', totalOrders);
console.log('Confirmed:', confirmed.length, '(' + (confirmed.length/totalOrders*100).toFixed(1) + '%)');
console.log('Cancelled:', cancelled.length, '(' + (cancelled.length/totalOrders*100).toFixed(1) + '%)');
console.log('Total revenue (confirmed):', '$' + totalRevenue);
console.log('Lost revenue (cancelled):', '$' + cancelledValue);
console.log('Avg order value (confirmed):', '$' + (totalRevenue/confirmed.length).toFixed(2));

// By customer
console.log('\n=== ORDERS BY CUSTOMER ===');
const byCustomer = {};
data.forEach(r => {
  if (!byCustomer[r.Customer]) byCustomer[r.Customer] = { orders: 0, confirmed: 0, cancelled: 0, revenue: 0 };
  byCustomer[r.Customer].orders++;
  if (r.Status === 'confirmed') { byCustomer[r.Customer].confirmed++; byCustomer[r.Customer].revenue += r['Total Paid']; }
  else byCustomer[r.Customer].cancelled++;
});
Object.entries(byCustomer).sort((a,b) => b[1].orders - a[1].orders).forEach(([c, v]) => {
  console.log(c + ': ' + v.orders + ' orders (' + v.confirmed + ' confirmed, ' + v.cancelled + ' cancelled) — $' + v.revenue + ' revenue');
});

// By date
console.log('\n=== ORDERS BY DATE ===');
const byDate = {};
data.forEach(r => {
  if (!byDate[r.Date]) byDate[r.Date] = { count: 0, revenue: 0 };
  if (r.Status === 'confirmed') { byDate[r.Date].count++; byDate[r.Date].revenue += r['Total Paid']; }
});
Object.entries(byDate).forEach(([d, v]) => console.log(d + ': ' + v.count + ' confirmed orders, $' + v.revenue));

// Product popularity
console.log('\n=== PRODUCT POPULARITY ===');
const products = {};
confirmed.forEach(r => {
  r.Items.split(', ').forEach(item => {
    products[item] = (products[item] || 0) + 1;
  });
});
Object.entries(products).sort((a,b) => b[1] - a[1]).forEach(([p, c]) => console.log(c + 'x  ' + p));

// Price range
const prices = confirmed.map(r => r['Total Paid']).sort((a,b) => a - b);
console.log('\n=== PRICE RANGE (confirmed) ===');
console.log('Min:', '$' + prices[0]);
console.log('Max:', '$' + prices[prices.length-1]);
console.log('Median:', '$' + prices[Math.floor(prices.length/2)]);
"

const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, BorderStyle, Table, TableRow, TableCell, WidthType } = require("docx");
const fs = require("fs");

async function generate() {
  const doc = new Document({
    styles: {
      default: {
        document: {
          run: { font: "Calibri", size: 22 },
        },
      },
    },
    sections: [
      {
        properties: {},
        children: [
          // Title
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { after: 400 },
            children: [
              new TextRun({ text: "Order Summary Analysis", bold: true, size: 40, font: "Calibri" }),
            ],
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { after: 400 },
            children: [
              new TextRun({ text: "Data source: order_summary.xlsx  •  Generated: " + new Date().toISOString().split("T")[0], italics: true, size: 20, color: "666666" }),
            ],
          }),

          // Horizontal rule via border
          new Paragraph({ spacing: { after: 300 }, border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: "CCCCCC" } } }),

          // === OVERVIEW ===
          new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 200, after: 200 }, children: [new TextRun({ text: "Overview", bold: true })] }),

          ...bullet("27 total orders across 17 unique customers"),
          ...bullet("24 confirmed (88.9%) / 3 cancelled (11.1%)"),
          ...bullet("$1,831 total confirmed revenue | $186 in lost/cancelled revenue"),
          ...bullet("Average order value: $76.29 (median: $71, range: $14–$201)"),

          // === KEY OBSERVATIONS ===
          new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 400, after: 200 }, children: [new TextRun({ text: "Key Observations", bold: true })] }),

          // 1. Heavy Customer Concentration
          new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 300, after: 150 }, children: [new TextRun({ text: "1. Heavy Customer Concentration", bold: true })] }),
          ...bodyText("Maya Chen is the top customer by a wide margin — 7 orders, $477 in revenue (26% of total). She also accounts for 2 of the 3 cancellations."),
          ...bodyText("Evan Parker follows with 4 orders and $276 in revenue. Notably, 3 of his 4 orders are identical ($71 each for the same two items) — possibly duplicate orders or a recurring purchase."),
          ...bodyText("The top 3 named customers (Maya Chen, Evan Parker, Alicia Morgan) account for $890 (48.6%) of all revenue."),

          // 2. Activity Clustered on One Day
          new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 300, after: 150 }, children: [new TextRun({ text: "2. Activity is Clustered on One Day", bold: true })] }),
          ...bodyText("25 of 27 orders were placed on 2026-09-02, with only 2 orders on 2026-09-04. This looks like a launch day, promotional event, or a data snapshot from a burst of activity."),

          // 3. Product Popularity
          new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 300, after: 150 }, children: [new TextRun({ text: "3. Product Popularity", bold: true })] }),
          ...bodyText("LogiTech Wireless Mouse M310 is the runaway bestseller, appearing in 13 of 24 confirmed orders (54%)."),
          ...bodyText("OXO SoftWorks 3-Piece Mixing Bowl Set is second with 7 appearances."),
          ...bodyText("The top 5 products (Mouse, Bowl Set, Canvas Tote, Desk Organizer, T-Shirt) cover the vast majority of items sold, while several products appear only once."),

          // Product popularity table
          new Paragraph({ spacing: { before: 200, after: 100 }, children: [new TextRun({ text: "Product Frequency (Confirmed Orders):", bold: true, italics: true, size: 20 })] }),
          createProductTable(),

          // 4. Cancellations
          new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 300, after: 150 }, children: [new TextRun({ text: "4. Cancellations", bold: true })] }),
          ...bodyText("All 3 cancellations occurred on the same date (Sept 2). Two were from Maya Chen and one from Jordan Alvarez (whose only order was cancelled, meaning $0 revenue from that customer)."),
          ...bodyText("The cancelled items (Bluetooth Speaker, Ergonomic Mouse, Bowl Set + Thermometer) don't overlap strongly with top sellers — no pattern suggesting a product-specific issue."),

          // 5. Anomalies
          new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 300, after: 150 }, children: [new TextRun({ text: "5. Anomalies", bold: true })] }),
          ...bodyText("Evan Parker's repeat orders (ORD-92C795, ORD-24A5B1, ORD-03E32D) are for the exact same items at the exact same price — worth investigating as potential duplicates."),
          ...bodyText("Several customers appear as anonymized user IDs (e.g., user_2f384bdb), suggesting guest checkouts or incomplete account registrations — a potential area to improve customer retention."),

          // Horizontal rule
          new Paragraph({ spacing: { before: 400, after: 200 }, border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: "CCCCCC" } } }),

          // Summary
          new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 200, after: 200 }, children: [new TextRun({ text: "Summary", bold: true })] }),
          ...bodyText("Revenue is healthy at $1,831 with a strong 88.9% confirmation rate. However, revenue is highly concentrated among a few customers and a single date. The LogiTech Wireless Mouse M310 dominates product sales. Key action items include: investigating Evan Parker's duplicate orders, converting anonymous users to registered accounts, and understanding the cancellation pattern from Maya Chen."),
        ],
      },
    ],
  });

  const buffer = await Packer.toBuffer(doc);
  fs.writeFileSync("data/order_analysis.docx", buffer);
  console.log("Document saved to data/order_analysis.docx");
}

function bullet(text) {
  return [
    new Paragraph({
      spacing: { after: 80 },
      bullet: { level: 0 },
      children: [new TextRun({ text, size: 22 })],
    }),
  ];
}

function bodyText(text) {
  return [
    new Paragraph({
      spacing: { after: 150 },
      children: [new TextRun({ text, size: 22 })],
    }),
  ];
}

function createProductTable() {
  const products = [
    ["LogiTech Wireless Mouse M310", "13"],
    ["OXO SoftWorks 3-Piece Mixing Bowl Set", "7"],
    ["Everyday Canvas Tote Bag", "5"],
    ["Bamboo Desk Organizer Set", "5"],
    ["Levi's Classic Cotton T-Shirt", "4"],
    ["Northline Wool Blend Throw Blanket", "4"],
    ["CableCraft USB-C Organizer Strap 2-Pack", "3"],
    ["Aurora Smart Desk Lamp Pro", "2"],
    ["Anker Portable Bluetooth Speaker", "1"],
    ["ThermoPro Digital Meat Thermometer", "1"],
    ["Wireless Mouse", "1"],
    ["OXO Good Grips Salad Spinner", "1"],
    ["RidgeLine Fleece Zip Hoodie", "1"],
    ["TrailPeak Insulated Travel Mug", "1"],
    ["AeroLoop Silicone Cable Organizer", "1"],
  ];

  const headerRow = new TableRow({
    tableHeader: true,
    children: [
      new TableCell({
        width: { size: 70, type: WidthType.PERCENTAGE },
        shading: { fill: "2E75B6" },
        children: [new Paragraph({ children: [new TextRun({ text: "Product", bold: true, color: "FFFFFF", size: 20 })] })],
      }),
      new TableCell({
        width: { size: 30, type: WidthType.PERCENTAGE },
        shading: { fill: "2E75B6" },
        children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Appearances", bold: true, color: "FFFFFF", size: 20 })] })],
      }),
    ],
  });

  const rows = products.map(([name, count], i) => {
    const fill = i % 2 === 0 ? "F2F2F2" : "FFFFFF";
    return new TableRow({
      children: [
        new TableCell({
          shading: { fill },
          children: [new Paragraph({ children: [new TextRun({ text: name, size: 20 })] })],
        }),
        new TableCell({
          shading: { fill },
          children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: count, size: 20 })] })],
        }),
      ],
    });
  });

  return new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    rows: [headerRow, ...rows],
  });
}

generate().catch(console.error);
